package com.onlinelibrary.dao.impl;
import com.onlinelibrary.dao.ReportDAO; import com.onlinelibrary.model.ReportSummary; import com.onlinelibrary.util.DBConnection; import java.sql.*; import java.util.*;
public class ReportDAOImpl implements ReportDAO {
 public ReportSummary summary()throws SQLException{String q="SELECT (SELECT COUNT(*) FROM books) total_books,(SELECT COALESCE(SUM(available_quantity),0) FROM books) available_copies,(SELECT COUNT(*) FROM transactions WHERE status IN ('BORROWED','OVERDUE')) borrowed_books,(SELECT COUNT(*) FROM transactions WHERE status='OVERDUE' OR (status='BORROWED' AND due_date<CURDATE())) overdue_books,(SELECT COUNT(*) FROM users WHERE role='MEMBER') total_members,(SELECT COUNT(*) FROM transactions) total_transactions";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q);ResultSet r=p.executeQuery()){r.next();ReportSummary s=new ReportSummary();s.setTotalBooks(r.getLong(1));s.setAvailableCopies(r.getLong(2));s.setBorrowedBooks(r.getLong(3));s.setOverdueBooks(r.getLong(4));s.setTotalMembers(r.getLong(5));s.setTotalTransactions(r.getLong(6));return s;}}
 public List<Map<String,Object>> mostBorrowed()throws SQLException{return rows("SELECT b.title,COUNT(t.id) borrow_count FROM books b LEFT JOIN transactions t ON t.book_id=b.id GROUP BY b.id,b.title ORDER BY borrow_count DESC,b.title LIMIT 10");}
 public List<Map<String,Object>> genreDistribution()throws SQLException{return rows("SELECT genre,COUNT(*) title_count,SUM(total_quantity) copy_count FROM books GROUP BY genre ORDER BY title_count DESC");}
 public List<Map<String,Object>> monthlyBorrowing()throws SQLException{return rows("SELECT DATE_FORMAT(borrow_date,'%Y-%m') month,COUNT(*) total FROM transactions GROUP BY DATE_FORMAT(borrow_date,'%Y-%m') ORDER BY month DESC LIMIT 12");}
 public List<Map<String,Object>> monthlyReturns()throws SQLException{return rows("SELECT DATE_FORMAT(return_date,'%Y-%m') month,COUNT(*) total FROM transactions WHERE return_date IS NOT NULL GROUP BY DATE_FORMAT(return_date,'%Y-%m') ORDER BY month DESC LIMIT 12");}
 private List<Map<String,Object>> rows(String sql)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(sql);ResultSet r=p.executeQuery()){List<Map<String,Object>>out=new ArrayList<>();ResultSetMetaData md=r.getMetaData();while(r.next()){Map<String,Object>m=new LinkedHashMap<>();for(int i=1;i<=md.getColumnCount();i++)m.put(md.getColumnLabel(i),r.getObject(i));out.add(m);}return out;}}
}
